pub mod message {
    use super::*;

    pub fn encode<M>(tag: u32, msg: &M, buf: &mut impl BufMut)
    where
        M: Message,
    {
        encode_key(tag, WireType::LengthDelimited, buf);
        encode_varint(msg.encoded_len() as u64, buf);
        msg.encode_raw(buf);
    }

    pub async fn encode_async<M, S>(
        tag: u32,
        msg: &M,
        sink: &mut S,
    ) -> Result<(), S::Error>
    where
        M: Message,
        S: AsyncEncodeSink + Send,
    {
        {
            let mut buf = sink.buf_mut();
            encode_key(tag, WireType::LengthDelimited, &mut buf);
            encode_varint(msg.encoded_len() as u64, &mut buf);
        }
        msg.encode_raw_async(sink).await
    }

    pub fn merge<M, B>(
        wire_type: WireType,
        msg: &mut M,
        buf: &mut B,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message,
        B: Buf,
    {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        ctx.limit_reached()?;
        merge_loop(
            msg,
            buf,
            ctx.enter_recursion(),
            |msg: &mut M, buf: &mut B, ctx| {
                let (tag, wire_type) = decode_key(buf)?;
                msg.merge_field(tag, wire_type, buf, ctx)
            },
        )
    }

    pub fn encode_repeated<M>(tag: u32, messages: &[M], buf: &mut impl BufMut)
    where
        M: Message,
    {
        for msg in messages {
            encode(tag, msg, buf);
        }
    }

    pub async fn encode_repeated_async<M, S>(
        tag: u32,
        messages: &[M],
        sink: &mut S,
    ) -> Result<(), S::Error>
    where
        M: Message,
        S: AsyncEncodeSink + Send,
    {
        for msg in messages {
            encode_async(tag, msg, sink).await?;
        }
        Ok(())
    }

    pub fn merge_repeated<M>(
        wire_type: WireType,
        messages: &mut Vec<M>,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message + Default,
    {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        let mut msg = M::default();
        merge(WireType::LengthDelimited, &mut msg, buf, ctx)?;
        messages.push(msg);
        Ok(())
    }

    #[inline]
    pub fn encoded_len<M>(tag: u32, msg: &M) -> usize
    where
        M: Message,
    {
        let len = msg.encoded_len();
        key_len(tag) + encoded_len_varint(len as u64) + len
    }

    #[inline]
    pub fn encoded_len_repeated<M>(tag: u32, messages: &[M]) -> usize
    where
        M: Message,
    {
        key_len(tag) * messages.len()
            + messages
                .iter()
                .map(Message::encoded_len)
                .map(|len| len + encoded_len_varint(len as u64))
                .sum::<usize>()
    }
}

pub mod group {
    use crate::error::DecodeErrorKind;

    use super::*;

    pub fn encode<M>(tag: u32, msg: &M, buf: &mut impl BufMut)
    where
        M: Message,
    {
        encode_key(tag, WireType::StartGroup, buf);
        msg.encode_raw(buf);
        encode_key(tag, WireType::EndGroup, buf);
    }

    pub async fn encode_async<M, S>(
        tag: u32,
        msg: &M,
        sink: &mut S,
    ) -> Result<(), S::Error>
    where
        M: Message,
        S: AsyncEncodeSink + Send,
    {
        {
            let mut buf = sink.buf_mut();
            encode_key(tag, WireType::StartGroup, &mut buf);
        }
        msg.encode_raw_async(sink).await?;
        {
            let mut buf = sink.buf_mut();
            encode_key(tag, WireType::EndGroup, &mut buf);
        }
        Ok(())
    }

    pub fn merge<M>(
        tag: u32,
        wire_type: WireType,
        msg: &mut M,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message,
    {
        check_wire_type(WireType::StartGroup, wire_type)?;

        ctx.limit_reached()?;
        loop {
            let (field_tag, field_wire_type) = decode_key(buf)?;
            if field_wire_type == WireType::EndGroup {
                if field_tag != tag {
                    return Err(DecodeErrorKind::UnexpectedEndGroupTag.into());
                }
                return Ok(());
            }

            M::merge_field(msg, field_tag, field_wire_type, buf, ctx.enter_recursion())?;
        }
    }

    pub fn encode_repeated<M>(tag: u32, messages: &[M], buf: &mut impl BufMut)
    where
        M: Message,
    {
        for msg in messages {
            encode(tag, msg, buf);
        }
    }

    pub async fn encode_repeated_async<M, S>(
        tag: u32,
        messages: &[M],
        sink: &mut S,
    ) -> Result<(), S::Error>
    where
        M: Message,
        S: AsyncEncodeSink + Send,
    {
        for msg in messages {
            encode_async(tag, msg, sink).await?;
        }
        Ok(())
    }

