    pub fn encode(&self, prost_path: &Path, ident: TokenStream) -> TokenStream {
        let module = self.ty.module();
        let encode_fn = match self.kind {
            Kind::Plain(..) | Kind::Optional(..) | Kind::Required(..) => quote!(encode),
            Kind::Repeated => quote!(encode_repeated),
            Kind::Packed => quote!(encode_packed),
        };
        let encode_fn = quote!(#prost_path::encoding::#module::#encode_fn);
        let tag = self.tag;

        match self.kind {
            Kind::Plain(ref default) => {
                let default = default.typed();
                quote! {
                    if #ident != #default {
                        #encode_fn(#tag, &#ident, buf);
                    }
                }
            }
            Kind::Optional(..) => quote! {
                if let ::core::option::Option::Some(ref value) = #ident {
                    #encode_fn(#tag, value, buf);
                }
            },
            Kind::Required(..) | Kind::Repeated | Kind::Packed => quote! {
                #encode_fn(#tag, &#ident, buf);
            },
        }
    }

    pub fn encode_async(&self, prost_path: &Path, ident: TokenStream) -> TokenStream {
        let tag = self.tag;

        match self.kind {
            Kind::Plain(ref default) => {
                let default = default.typed();
                let encode =
                    encode_value_async(prost_path, &self.ty, quote!(#tag), quote!(&#ident));
                quote! {
                    if #ident != #default {
                        #encode
                    }
                }
            }
            Kind::Optional(..) => {
                let encode = encode_value_async(prost_path, &self.ty, quote!(#tag), quote!(value));
                quote! {
                    if let ::core::option::Option::Some(ref value) = #ident {
                        #encode
                    }
                }
            }
            Kind::Required(..) => {
                encode_value_async(prost_path, &self.ty, quote!(#tag), quote!(&#ident))
            }
            Kind::Repeated if matches!(self.ty, Ty::String | Ty::Bytes(..)) => {
                let module = self.ty.module();
                quote! {
                    #prost_path::encoding::#module::encode_repeated_async(#tag, &#ident, sink).await?;
                }
            }
            Kind::Repeated => {
                let module = self.ty.module();
                quote! {
                    {
                        let mut buf = #prost_path::transfer::AsyncEncodeSink::buf_mut(sink);
                        #prost_path::encoding::#module::encode_repeated(#tag, &#ident, &mut buf);
                    }
                }
            }
            Kind::Packed => {
                let module = self.ty.module();
                quote! {
                    {
                        let mut buf = #prost_path::transfer::AsyncEncodeSink::buf_mut(sink);
                        #prost_path::encoding::#module::encode_packed(#tag, &#ident, &mut buf);
                    }
                }
            }
        }
    }

