struct DsaProstEncodeSink {
…
    work_queue: Option<SharedDsaWorkQueue>,
}

impl DsaProstEncodeSink {
    fn new(buf: EncodeBuffer, work_queue: Option<SharedDsaWorkQueue>) -> Self {
        Self { buf, work_queue }
    }

    fn into_inner(self) -> EncodeBuffer {
        self.buf
    }

    fn selected_work_queue(&self, payload_len: usize) -> Option<SharedDsaWorkQueue> {
        self.work_queue
            .as_ref()
            .filter(|work_queue| work_queue.accelerates(payload_len))
            .cloned()
    }
}

impl AsyncEncodeSink for DsaProstEncodeSink {
    type Error = Status;

    type BufMut<'a>
        = EncodeBuf<'a>
    where
        Self: 'a;

    fn encode_error(error: prost::EncodeError) -> Self::Error {
        Status::internal(error.to_string())
    }

    fn buf_mut(&mut self) -> Self::BufMut<'_> {
        self.buf.as_encode_buf()
    }

    fn put_payload<'a>(
        &'a mut self,
        payload: &'a [u8],
    ) -> impl Future<Output = Result<(), Self::Error>> + Send + 'a {
        match self.selected_work_queue(payload.len()) {
            None => {
                self.buf.as_encode_buf().put_slice(payload);
                DsaProstPayloadCopy::ready(Ok(()))
            }
            Some(_) if payload.len() > u32::MAX as usize => DsaProstPayloadCopy::ready(Err(
                Status::internal(format!(
                    "async dsa prost encode cannot copy {} bytes; maximum DSA transfer is {} bytes",
                    payload.len(),
                    u32::MAX
                )),
            )),
            Some(work_queue) => DsaProstPayloadCopy::dsa(work_queue, payload, &mut self.buf),
        }
    }
}

enum DsaProstPayloadCopy<'a> {
    Ready(Ready<Result<(), Status>>),
    Dsa(Pin<Box<PendingDsaProstPayloadCopy<'a>>>),
}

impl fmt::Debug for DsaProstPayloadCopy<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DsaProstPayloadCopy::Ready(_) => f.write_str("DsaProstPayloadCopy::Ready"),
            DsaProstPayloadCopy::Dsa(_) => f.write_str("DsaProstPayloadCopy::Dsa"),
        }
    }
}

impl<'a> DsaProstPayloadCopy<'a> {
    fn ready(result: Result<(), Status>) -> Self {
        Self::Ready(ready(result))
    }

