+    #[test]
+    fn prost_encoder_without_work_queue_uses_cpu_path() {
+        let msg = LargeFields {
+            name: "cpu prost string".repeat(16),
+            payload: Bytes::from(vec![0x5a; 1024]),
+            id: 7,
+        };
+        let data = encode_one_frame(
