    type Error: From<EncodeError> + Send + Sync + 'static;

    /// Owned future returned for one encode operation.
    type Encode<M, B>: Future<Output = Result<B, Self::Error>> + Send + 'static
    where
        M: Message + Send + 'static,
        B: EncodeDst + Send + 'static;

