enum DsaProstPayloadCopy<'a> {
    Ready(Ready<Result<(), Status>>),
    Dsa(Pin<Box<PendingDsaProstPayloadCopy<'a>>>),
    #[cfg(test)]
    YieldingCpu(PendingYieldingProstPayloadCopy<'a>),
}

impl fmt::Debug for DsaProstPayloadCopy<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DsaProstPayloadCopy::Ready(_) => f.write_str("DsaProstPayloadCopy::Ready"),
            DsaProstPayloadCopy::Dsa(_) => f.write_str("DsaProstPayloadCopy::Dsa"),
            #[cfg(test)]
            DsaProstPayloadCopy::YieldingCpu(_) => f.write_str("DsaProstPayloadCopy::YieldingCpu"),
        }
    }
}

impl<'a> DsaProstPayloadCopy<'a> {
    fn ready(result: Result<(), Status>) -> Self {
        Self::Ready(ready(result))
    }

    fn dsa(work_queue: SharedDsaWorkQueue, source: &'a [u8], buf: &'a mut EncodeBuffer) -> Self {
        Self::Dsa(PendingDsaProstPayloadCopy::new(work_queue, source, buf))
    }

    #[cfg(test)]
    fn yielding_cpu(source: &'a [u8], buf: &'a mut EncodeBuffer) -> Self {
        Self::YieldingCpu(PendingYieldingProstPayloadCopy::new(source, buf))
    }
}

impl Future for DsaProstPayloadCopy<'_> {
    type Output = Result<(), Status>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        match this {
            DsaProstPayloadCopy::Ready(ready) => Pin::new(ready).poll(cx),
            DsaProstPayloadCopy::Dsa(copy) => copy.as_mut().poll(cx),
            #[cfg(test)]
            DsaProstPayloadCopy::YieldingCpu(copy) => copy.poll(cx),
        }
    }
}

#[cfg(test)]
struct PendingYieldingProstPayloadCopy<'a> {
    source: &'a [u8],
    buf: &'a mut EncodeBuffer,
