pub mod message {
    use super::*;

    pub fn encode<M>(tag: u32, msg: &M, buf: &mut impl BufMut)
    where
        M: Message,
    {
        encode_key(tag, WireType::LengthDelimited, buf);
        encode_varint(msg.encoded_len() as u64, buf);
        msg.encode_raw(buf);
    }

    pub fn encode_async<'a, M, S>(
        tag: u32,
        msg: &'a M,
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, M, S>
    where
        M: Message + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            {
                let mut buf = sink.buf_mut();
                encode_key(tag, WireType::LengthDelimited, &mut buf);
                encode_varint(msg.encoded_len() as u64, &mut buf);
            }
            msg.encode_raw_async(sink).await
        }
    }

    pub fn merge<M, B>(
        wire_type: WireType,
        msg: &mut M,
        buf: &mut B,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message,
        B: Buf,
    {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        ctx.limit_reached()?;
        merge_loop(
            msg,
            buf,
            ctx.enter_recursion(),
            |msg: &mut M, buf: &mut B, ctx| {
                let (tag, wire_type) = decode_key(buf)?;
                msg.merge_field(tag, wire_type, buf, ctx)
            },
        )
    }

    pub fn encode_repeated<M>(tag: u32, messages: &[M], buf: &mut impl BufMut)
    where
        M: Message,
    {
        for msg in messages {
            encode(tag, msg, buf);
        }
    }

    pub fn encode_repeated_async<'a, M, S>(
        tag: u32,
        messages: &'a [M],
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, M, S>
    where
        M: Message + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
