    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("PendingDsaProstPayloadCopy")
    }
}

// SAFETY: `dst` points into the `EncodeBuffer` borrowed by this pending state.
// The borrowed source bytes, destination buffer, descriptor, and completion
// record remain alive until completion. `Drop` drains a submitted descriptor
// before those borrows can be released.
unsafe impl Send for PendingDsaProstPayloadCopy<'_> {}

impl<'a> PendingDsaProstPayloadCopy<'a> {
    fn new(work_queue: SharedDsaWorkQueue, source: &'a [u8], buf: &'a mut EncodeBuffer) -> Self {
        Self {
            work_queue,
            source,
            buf,
            dst: std::ptr::null_mut(),
            dst_len: 0,
            desc: DsaHwDesc::default(),
            completion: DsaCompletionRecord::default(),
            retry: None,
            submitted: false,
            completed: false,
            _pin: PhantomPinned,
        }
    }

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<(), Status>> {
        // SAFETY: This method never moves fields out of the pinned allocation.
        // It only mutates scalar state and borrows the owned descriptor,
        // completion record, and encode buffer in place.
        let this = unsafe { self.as_mut().get_unchecked_mut() };

        if !this.submitted {
            let len = this.source.len();
            let mut dst = this.buf.as_encode_buf();
            // SAFETY: The pending state holds exclusive access to the encode
            // buffer until completion. The matching advance happens exactly
            // once after DSA reports success for this reservation.
            let dst_ptr = unsafe { dst.reserve_uninit_slice_for_pending(len) };
            touch_pages_for_dsa(this.source.as_ptr(), dst_ptr, len);

            let retry = DsaMemmoveRetry::new(this.source.as_ptr(), dst_ptr, len);
            submit_retry(
                &this.work_queue,
                &mut this.desc,
                &mut this.completion,
                &retry,
            )?;
            this.retry = Some(retry);
            this.dst = dst_ptr;
            this.dst_len = len;
            this.submitted = true;
        }

        if this.completion.status() == DsaCompletionStatus::None.as_u8() {
            cx.waker().wake_by_ref();
            return Poll::Pending;
        }

        let retry = this.retry.as_mut().expect("pending retry state available");
        match retry.handle_completion(this.completion, &this.work_queue.config.device_path) {
            Ok(DsaRetryAction::Complete) => {
                this.completed = true;
                // SAFETY: DSA success means the descriptor initialized exactly
                // the bytes reserved for this payload copy.
                unsafe {
                    this.buf
                        .as_encode_buf()
                        .advance_reserved_uninit_slice(this.dst_len);
                }
                Poll::Ready(Ok(()))
            }
            Ok(DsaRetryAction::Retry) => {
                submit_retry(
                    &this.work_queue,
                    &mut this.desc,
                    &mut this.completion,
                    retry,
                )?;
                cx.waker().wake_by_ref();
                Poll::Pending
            }
            Err(status) => {
                this.completed = true;
                Poll::Ready(Err(status))
            }
        }
    }

    fn drain_completion(&mut self) {
        if !self.submitted || self.completed {
            return;
        }

        while self.completion.status() == DsaCompletionStatus::None.as_u8() {
            core::hint::spin_loop();
        }
        self.completed = true;
    }
}

impl Drop for PendingDsaProstPayloadCopy<'_> {
    fn drop(&mut self) {
        self.drain_completion();
    }
}

