use anyhow::{bail, Context, Error};
use itertools::Itertools;
use proc_macro2::{Span, TokenStream};
use quote::quote;
use syn::{
    punctuated::Punctuated, Data, DataEnum, DataStruct, DeriveInput, Expr, ExprLit, Fields,
    FieldsNamed, FieldsUnnamed, GenericParam, Ident, Index, Variant,
};
use syn::{Attribute, Lit, Meta, MetaNameValue, Path, Token};

mod field;
use crate::field::Field;

use self::field::set_option;

fn try_message(input: TokenStream) -> Result<TokenStream, Error> {
    let input: DeriveInput = syn::parse2(input)?;
    let ident = input.ident;

    let Attributes {
        skip_debug,
        prost_path,
    } = Attributes::new(input.attrs)?;

    let variant_data = match input.data {
        Data::Struct(variant_data) => variant_data,
        Data::Enum(..) => bail!("Message can not be derived for an enum"),
        Data::Union(..) => bail!("Message can not be derived for a union"),
    };

    let generics = &input.generics;
    let (impl_generics, ty_generics, where_clause) = generics.split_for_impl();

    let async_precise_captures = precise_captures_for_async_return(generics);
    let (is_struct, fields) = match variant_data {
        DataStruct {
            fields: Fields::Named(FieldsNamed { named: fields, .. }),
            ..
        } => (true, fields.into_iter().collect()),
…
    };
…
    let methods = if methods.is_empty() {
…
    } else {
        quote! {
…
        }
    };

    let encode_raw_async = if fields.iter().any(|(_, field)| field.needs_async_encode()) {
        let encode_async = fields
            .iter()
            .map(|(field_ident, field)| field.encode_async(&prost_path, quote!(self.#field_ident)));

        quote! {
            #[allow(unused_variables)]
            fn encode_raw_async<'a, S>(
                &'a self,
                sink: &'a mut S,
            ) -> impl ::core::future::Future<Output = ::core::result::Result<(), S::Error>> + Send + 'a + #async_precise_captures
            where
                Self: 'a,
                S: #prost_path::transfer::AsyncEncodeSink + Send + 'a,
            {
                async move {
                    #(#encode_async)*
                    ::core::result::Result::Ok(())
                }
            }
        }
    } else {
        quote!()
    };

    let expanded = quote! {
        impl #impl_generics #prost_path::Message for #ident #ty_generics #where_clause {
            #[allow(unused_variables)]
            fn encode_raw(&self, buf: &mut impl #prost_path::bytes::BufMut) {
                #(#encode)*
            }

            #encode_raw_async

            #[allow(unused_variables)]
            fn merge_field(
                &mut self,
                tag: u32,
…
            ) -> ::core::result::Result<(), #prost_path::DecodeError>
…
        }
…
    };
…
    Ok(expanded)
}

fn precise_captures_for_async_return(generics: &syn::Generics) -> TokenStream {
    let captures = generics
        .params
        .iter()
        .map(|param| match param {
            GenericParam::Lifetime(param) => {
                let lifetime = &param.lifetime;
                quote!(#lifetime)
            }
            GenericParam::Type(param) => {
                let ident = &param.ident;
                quote!(#ident)
            }
            GenericParam::Const(param) => {
                let ident = &param.ident;
                quote!(#ident)
            }
        })
        .collect::<Vec<_>>();

    if captures.is_empty() {
        quote!(use<'a, S>)
    } else {
        quote!(use<'a, S, #(#captures),*>)
    }
}

