impl<T> Encoder for DsaAsyncProstEncoder<T>
where
    T: Message + Send + 'static,
{
    type Item = T;
    type Error = Status;
    type Encode = DsaAsyncProstEncode;

    fn encode(
        self: Pin<&mut Self>,
        item: Self::Item,
        dst: EncodeBuffer,
    ) -> Result<Self::Encode, Self::Error> {
        let work_queue = self.as_ref().get_ref().work_queue.clone();
        #[cfg(test)]
        let yielding_cpu_for_tests = self.as_ref().get_ref().yielding_cpu_for_tests;
        let future = async move {
            #[cfg(not(test))]
            let mut sink = DsaProstEncodeSink::new(dst, work_queue);
            #[cfg(test)]
            let mut sink =
                DsaProstEncodeSink::new_for_tests(dst, work_queue, yielding_cpu_for_tests);
            encode_message_to_sink(&item, &mut sink, EncodeOptions::default()).await?;
            Ok(sink.into_inner())
        };

        Ok(DsaAsyncProstEncode {
            inner: Box::pin(future),
        })
    }

    fn buffer_settings(&self) -> BufferSettings {
        self.buffer_settings
    }
}

/// Owned future returned by [`DsaAsyncProstEncoder`] for one message encode.
pub struct DsaAsyncProstEncode {
    inner: Pin<Box<dyn Future<Output = Result<EncodeBuffer, Status>> + Send>>,
}

impl fmt::Debug for DsaAsyncProstEncode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("DsaAsyncProstEncode")
    }
}

impl Future for DsaAsyncProstEncode {
    type Output = Result<EncodeBuffer, Status>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        self.inner.as_mut().poll(cx)
    }
}

