impl AsyncEncodeSink for DsaProstEncodeSink {
    type Error = Status;

    type BufMut<'a>
        = EncodeBuf<'a>
    where
        Self: 'a;

    fn encode_error(error: prost::EncodeError) -> Self::Error {
        Status::internal(error.to_string())
    }

    fn buf_mut(&mut self) -> Self::BufMut<'_> {
        self.buf.as_encode_buf()
    }

    fn put_payload<'a>(
        &'a mut self,
        payload: &'a [u8],
    ) -> impl Future<Output = Result<(), Self::Error>> + Send + 'a {
        #[cfg(test)]
        if self.yielding_cpu_for_tests {
            return DsaProstPayloadCopy::yielding_cpu(payload, &mut self.buf);
        }

        match self.selected_work_queue(payload.len()) {
            None => {
                self.buf.as_encode_buf().put_slice(payload);
                DsaProstPayloadCopy::ready(Ok(()))
            }
            Some(_) if payload.len() > u32::MAX as usize => {
                DsaProstPayloadCopy::ready(Err(Status::internal(format!(
                    "async dsa prost encode cannot copy {} bytes; maximum DSA transfer is {} bytes",
                    payload.len(),
                    u32::MAX
                ))))
            }
            Some(work_queue) => DsaProstPayloadCopy::dsa(work_queue, payload, &mut self.buf),
        }
    }
}

enum DsaProstPayloadCopy<'a> {
    Ready(Ready<Result<(), Status>>),
    Dsa(PendingDsaProstPayloadCopy<'a>),
    #[cfg(test)]
    YieldingCpu(PendingYieldingProstPayloadCopy<'a>),
}

