//! Owned asynchronous transfer APIs for Protocol Buffers messages.
//!
//! The default [`CpuEngine`] preserves prost's existing synchronous encoding
//! behavior while giving callers an owned future-shaped boundary for engines
//! that need to keep message and destination state across `Poll::Pending`.

use alloc::vec::Vec;
use bytes::{BufMut, BytesMut};
use core::future::Future;
use core::pin::Pin;
use core::task::{Context, Poll};

use crate::encoding::varint::{encode_varint, encoded_len_varint};
use crate::{EncodeError, Message};

/// Options that control how a message is encoded by an [`EncodeEngine`].
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct EncodeOptions {
    /// Encode the message with a protobuf length delimiter.
    pub length_delimited: bool,
}

/// Owned destination storage for an asynchronous encode operation.
///
/// Engines receive the destination by value and borrow its [`BufMut`] view only
/// while writing bytes. Engines that need stronger guarantees can define their
/// own destination type without changing generated message structs.
pub trait EncodeDst {
    /// Borrowed mutable protobuf byte sink exposed by this destination.
    type BufMut<'a>: BufMut
    where
        Self: 'a;

    /// Returns the byte sink used for this encode operation.
    fn as_buf_mut(&mut self) -> Self::BufMut<'_>;
}

impl EncodeDst for Vec<u8> {
    type BufMut<'a> = &'a mut Vec<u8>;

    #[inline]
    fn as_buf_mut(&mut self) -> Self::BufMut<'_> {
        self
    }
}

impl EncodeDst for BytesMut {
    type BufMut<'a> = &'a mut BytesMut;

    #[inline]
    fn as_buf_mut(&mut self) -> Self::BufMut<'_> {
        self
    }
}

/// Mutable destination used by generated asynchronous Prost encoding.
///
/// The sink exposes a short-lived [`BufMut`] view for protobuf structure
/// writes, and a separate payload-copy hook for `string` / `bytes` field
/// contents. The default CPU sink copies payloads immediately; experimental
/// sinks can return [`Poll::Pending`] while an external copy engine initializes
/// the destination bytes.
pub trait AsyncEncodeSink {
    /// Error produced while starting or completing an asynchronous encode.
    type Error: Send + Sync + 'static;

    /// Borrowed protobuf byte sink for CPU-written keys, lengths, and scalars.
    type BufMut<'a>: BufMut + Send
    where
        Self: 'a;

    /// Per-payload state kept by poll-based generated encoders while a sink
    /// copy is pending.
    type PayloadState: Default + Send;

    /// Converts a Prost capacity error into this sink's error type.
    fn encode_error(error: EncodeError) -> Self::Error;

    /// Returns the byte sink used for CPU-written protobuf structure.
    fn buf_mut(&mut self) -> Self::BufMut<'_>;

    /// Copies a `string` or `bytes` payload into the destination.
    fn poll_put_payload(
        &mut self,
        payload: &[u8],
        state: Pin<&mut Self::PayloadState>,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), Self::Error>>;

    /// Future-shaped adapter around [`AsyncEncodeSink::poll_put_payload`].
    fn put_payload<'a>(&'a mut self, payload: &'a [u8]) -> PutPayload<'a, Self>
    where
        Self: Sized,
    {
        PutPayload::new(self, payload)
    }
}

/// Universal generated-message state for poll-based async encoding.
pub struct PollEncodeState<S: AsyncEncodeSink> {
    field: usize,
    index: usize,
    phase: u8,
    payload: S::PayloadState,
}

impl<S: AsyncEncodeSink> Default for PollEncodeState<S> {
    fn default() -> Self {
        Self {
            field: 0,
            index: 0,
            phase: 0,
            payload: S::PayloadState::default(),
        }
    }
}

impl<S: AsyncEncodeSink> PollEncodeState<S> {
    #[inline]
    pub fn clear(&mut self) {
        self.field = 0;
        self.index = 0;
        self.phase = 0;
        self.reset_payload();
    }

    #[inline]
    pub fn field(&self) -> usize {
        self.field
    }

    #[inline]
    pub fn advance_field(&mut self) {
        self.field += 1;
        self.index = 0;
        self.phase = 0;
        self.reset_payload();
    }

    #[inline]
    pub fn index(&self) -> usize {
        self.index
    }

    #[inline]
    pub fn set_index(&mut self, index: usize) {
        self.index = index;
    }

    #[inline]
    pub fn phase(&self) -> u8 {
        self.phase
    }

    #[inline]
    pub fn set_phase(&mut self, phase: u8) {
        self.phase = phase;
    }

    #[inline]
    pub fn payload_pin_mut(&mut self) -> Pin<&mut S::PayloadState> {
        // SAFETY: `PollEncodeState` is driven from a pinned encode future in
        // the async paths that can return `Pending`. CPU paths complete
        // synchronously and do not rely on pinning.
        unsafe { Pin::new_unchecked(&mut self.payload) }
    }

    #[inline]
    pub fn reset_payload(&mut self) {
        self.payload = S::PayloadState::default();
    }
}
/// Future-shaped adapter for a single payload copy.
pub struct PutPayload<'a, S: AsyncEncodeSink> {
    sink: &'a mut S,
    payload: &'a [u8],
    state: S::PayloadState,
}

impl<'a, S: AsyncEncodeSink> PutPayload<'a, S> {
    #[inline]
    fn new(sink: &'a mut S, payload: &'a [u8]) -> Self {
        Self {
            sink,
            payload,
            state: S::PayloadState::default(),
        }
    }
}

impl<S> Future for PutPayload<'_, S>
where
    S: AsyncEncodeSink + Send,
{
    type Output = Result<(), S::Error>;

    #[inline]
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // SAFETY: the future is pinned before polling, and the payload state is
        // only accessed in place until it is dropped.
        let this = unsafe { self.get_unchecked_mut() };
        let state = unsafe { Pin::new_unchecked(&mut this.state) };
        this.sink.poll_put_payload(this.payload, state, cx)
    }
}

/// Future-shaped adapter around [`Message::poll_encode_raw`].
pub struct EncodeRawAsync<'a, M, S>
where
    M: Message,
    S: AsyncEncodeSink,
{
    message: &'a M,
    sink: &'a mut S,
    state: PollEncodeState<S>,
}

impl<'a, M, S> EncodeRawAsync<'a, M, S>
where
    M: Message,
    S: AsyncEncodeSink,
{
    #[inline]
    pub(crate) fn new(message: &'a M, sink: &'a mut S) -> Self {
        Self {
            message,
            sink,
            state: PollEncodeState::default(),
        }
    }
}

impl<M, S> Future for EncodeRawAsync<'_, M, S>
where
    M: Message,
    S: AsyncEncodeSink + Send,
{
    type Output = Result<(), S::Error>;

    #[inline]
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // SAFETY: once this future is pinned, its poll state is accessed in
        // place until completion or drop.
        let this = unsafe { self.get_unchecked_mut() };
        this.message.poll_encode_raw(this.sink, &mut this.state, cx)
    }
}

/// CPU-backed [`AsyncEncodeSink`] adapter for an existing [`BufMut`].
#[derive(Debug)]
pub struct BufMutEncodeSink<'a, B> {
    buf: &'a mut B,
}

impl<'a, B> BufMutEncodeSink<'a, B> {
    /// Wraps a mutable protobuf byte sink.
    #[inline]
    pub fn new(buf: &'a mut B) -> Self {
        Self { buf }
    }
}

impl<B> AsyncEncodeSink for BufMutEncodeSink<'_, B>
where
    B: BufMut + Send,
{
    type Error = EncodeError;

    type BufMut<'a>
        = &'a mut B
    where
        Self: 'a;

    type PayloadState = ();

    #[inline]
    fn encode_error(error: EncodeError) -> Self::Error {
        error
    }

    #[inline]
    fn buf_mut(&mut self) -> Self::BufMut<'_> {
        self.buf
    }

    #[inline]
    fn poll_put_payload(
        &mut self,
        payload: &[u8],
        _state: Pin<&mut Self::PayloadState>,
        _cx: &mut Context<'_>,
    ) -> Poll<Result<(), Self::Error>> {
        self.buf.put_slice(payload);
        Poll::Ready(Ok(()))
    }
}

/// Encodes `message` into an asynchronous sink.
///
/// This helper preserves Prost's existing capacity check and length-delimited
/// framing behavior, then delegates the message body to
/// [`Message::encode_raw_async`].
pub async fn encode_message_to_sink<M, S>(
    message: &M,
    sink: &mut S,
    options: EncodeOptions,
) -> Result<(), S::Error>
where
    M: Message,
    S: AsyncEncodeSink + Send,
{
    let len = message.encoded_len();
    let required = if options.length_delimited {
        len + encoded_len_varint(len as u64)
    } else {
        len
    };
    let remaining = {
        let buf = sink.buf_mut();
        buf.remaining_mut()
    };
    if required > remaining {
        return Err(S::encode_error(EncodeError::new(required, remaining)));
    }

    if options.length_delimited {
        let mut buf = sink.buf_mut();
        encode_varint(len as u64, &mut buf);
    }

    message.encode_raw_async(sink).await
}

/// Engine that owns message transfer from a prost message into a destination.
///
/// The trait is intentionally separate from [`Message`], so generated structs
/// and existing synchronous call sites do not grow hardware-specific methods or
/// required async hooks.
pub trait EncodeEngine: Clone + Send + Sync + 'static {
    /// Error produced while starting or completing an encode operation.
    type Error: From<EncodeError> + Send + Sync + 'static;

    /// Owned future returned for one encode operation.

